{
  "name": "mini-template",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "bun test",
    "typecheck": "bunx tsc --noEmit"
  }
}
type Position = { line: number; column: number };

type TextNode = { kind: "text"; value: string };
type ValueNode = { kind: "value"; path: string; escaped: boolean; position: Position };
type BlockNode = {
  kind: "if" | "each";
  path: string;
  truthy: Node[];
  falsy: Node[];
  position: Position;
};
type Node = TextNode | ValueNode | BlockNode;

type Frame = {
  block: BlockNode;
  parent: Node[];
  inElse: boolean;
};

type Context = {
  root: unknown;
  current: unknown;
  index: number | undefined;
};

function fail(message: string, position: Position): never {
  throw new Error(`${message} at line ${position.line}, column ${position.column}`);
}

function positionAt(source: string, offset: number): Position {
  let line = 1;
  let column = 1;
  for (let i = 0; i < offset; i++) {
    if (source.charCodeAt(i) === 10) {
      line++;
      column = 1;
    } else {
      column++;
    }
  }
  return { line, column };
}

function requirePath(path: string, tag: string, position: Position): string {
  if (!path) fail(`${tag} requires a path`, position);
  return path;
}

function parse(template: string): Node[] {
  const root: Node[] = [];
  let output = root;
  const stack: Frame[] = [];
  let cursor = 0;

  while (cursor < template.length) {
    const open = template.indexOf("{{", cursor);
    if (open === -1) {
      output.push({ kind: "text", value: template.slice(cursor) });
      break;
    }
    if (open > cursor) output.push({ kind: "text", value: template.slice(cursor, open) });

    const position = positionAt(template, open);
    const triple = template.startsWith("{{{", open);
    const closeToken = triple ? "}}}" : "}}";
    const contentStart = open + (triple ? 3 : 2);
    const close = template.indexOf(closeToken, contentStart);
    if (close === -1) fail("Unclosed tag", position);

    const content = template.slice(contentStart, close).trim();
    cursor = close + closeToken.length;

    if (triple) {
      output.push({
        kind: "value",
        path: requirePath(content, "Interpolation", position),
        escaped: false,
        position,
      });
      continue;
    }

    if (content.startsWith("!")) continue;

    if (content.startsWith("#")) {
      const match = /^#([^\s]+)(?:\s+(.*))?$/.exec(content);
      const name = match?.[1] ?? "";
      if (name !== "if" && name !== "each") fail(`Unknown block '${name}'`, position);
      const block: BlockNode = {
        kind: name,
        path: requirePath(match?.[2]?.trim() ?? "", `#${name}`, position),
        truthy: [],
        falsy: [],
        position,
      };
      output.push(block);
      stack.push({ block, parent: output, inElse: false });
      output = block.truthy;
      continue;
    }

    if (content === "else") {
      const frame = stack.at(-1);
      if (!frame) fail("else outside a block", position);
      if (frame.inElse) fail("Duplicate else", position);
      frame.inElse = true;
      output = frame.block.falsy;
      continue;
    }

    if (content.startsWith("/")) {
      const name = content.slice(1).trim();
      const frame = stack.at(-1);
      if (!frame) fail(`Closing block '/${name}' without an open block`, position);
      if (name !== "if" && name !== "each") fail(`Unknown closing block '/${name}'`, position);
      if (frame.block.kind !== name) {
        fail(`Mismatched closing block '/${name}'; expected '/${frame.block.kind}'`, position);
      }
      stack.pop();
      output = frame.parent;
      continue;
    }

    output.push({
      kind: "value",
      path: requirePath(content, "Interpolation", position),
      escaped: true,
      position,
    });
  }

  const unclosed = stack.at(-1)?.block;
  if (unclosed) fail(`Unclosed block '#${unclosed.kind}'`, unclosed.position);
  return root;
}

function property(value: unknown, key: string): unknown {
  if ((typeof value !== "object" || value === null) && typeof value !== "function") {
    return undefined;
  }
  return Object.prototype.hasOwnProperty.call(value, key)
    ? (value as Record<string, unknown>)[key]
    : undefined;
}

function traverse(value: unknown, parts: string[]): unknown {
  for (const part of parts) {
    value = property(value, part);
    if (value === undefined) break;
  }
  return value;
}

function resolve(path: string, context: Context): unknown {
  if (path === "this") return context.current;
  if (path === "@index") return context.index;

  if (path.startsWith("this.")) return traverse(context.current, path.slice(5).split("."));
  if (path.startsWith("@index.")) return undefined;

  const parts = path.split(".");
  const local = traverse(context.current, parts);
  return local === undefined && context.current !== context.root
    ? traverse(context.root, parts)
    : local;
}

function isTruthy(value: unknown): boolean {
  if (Array.isArray(value)) return value.length > 0;
  return value !== "" && value !== 0 && value !== false && value !== null && value !== undefined;
}

function scalar(value: unknown, path: string, position: Position): string {
  if (value === null || value === undefined) return "";
  if (
    typeof value === "string" ||
    typeof value === "number" ||
    typeof value === "boolean" ||
    typeof value === "bigint"
  ) {
    return String(value);
  }
  fail(`Value '${path}' is not renderable as scalar text (received ${typeof value})`, position);
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) => {
    switch (character) {
      case "&": return "&amp;";
      case "<": return "&lt;";
      case ">": return "&gt;";
      case "\"": return "&quot;";
      default: return "&#39;";
    }
  });
}

function renderNodes(nodes: Node[], context: Context): string {
  let result = "";
  for (const node of nodes) {
    if (node.kind === "text") {
      result += node.value;
      continue;
    }
    if (node.kind === "value") {
      const text = scalar(resolve(node.path, context), node.path, node.position);
      result += node.escaped ? escapeHtml(text) : text;
      continue;
    }

    const value = resolve(node.path, context);
    if (node.kind === "if") {
      result += renderNodes(isTruthy(value) ? node.truthy : node.falsy, context);
    } else if (Array.isArray(value) && value.length > 0) {
      for (let index = 0; index < value.length; index++) {
        result += renderNodes(node.truthy, {
          root: context.root,
          current: value[index],
          index,
        });
      }
    } else {
      result += renderNodes(node.falsy, context);
    }
  }
  return result;
}

/** Render a Mini Template string with the supplied data. */
export function render(template: string, data: unknown): string {
  return renderNodes(parse(template), { root: data, current: data, index: undefined });
}
import { render } from "./engine";

async function main(): Promise<void> {
  const [templatePath, dataPath, ...extra] = Bun.argv.slice(2);
  if (!templatePath || !dataPath || extra.length > 0) {
    throw new Error("Usage: bun run src/cli.ts TEMPLATE_FILE DATA.json");
  }

  const [template, json] = await Promise.all([
    Bun.file(templatePath).text(),
    Bun.file(dataPath).text(),
  ]);
  const data: unknown = JSON.parse(json);
  process.stdout.write(render(template, data));
}

main().catch((error: unknown) => {
  const message = error instanceof Error ? error.message : String(error);
  process.stderr.write(`mini-template: ${message}\n`);
  process.exitCode = 1;
});
import { describe, expect, test } from "bun:test";
import { render } from "./engine";

describe("render", () => {
  test("interpolates escaped, raw, missing, and comment values", () => {
    const data = { value: `<a href='x'>&"`, raw: "<b>ok</b>" };
    expect(render("{{value}}|{{{raw}}}|{{missing}}{{! ignored }}", data)).toBe(
      "&lt;a href=&#39;x&#39;&gt;&amp;&quot;|<b>ok</b>|",
    );
  });

  test("preserves whitespace and follows the specified truthiness", () => {
    const template = " A\n{{#if value}}yes{{else}}no{{/if}}\nZ ";
    for (const value of ["", 0, false, null, undefined, []]) {
      expect(render(template, { value })).toBe(" A\nno\nZ ");
    }
    for (const value of ["x", 1, true, {}, [0]]) {
      expect(render(template, { value })).toBe(" A\nyes\nZ ");
    }
  });

  test("supports nested each, indexes, this paths, root fallback, and else", () => {
    const template =
      "{{#each groups}}[{{@index}}:{{this.name}}/{{title}}:" +
      "{{#each items}}{{@index}}={{this}};{{else}}empty{{/each}}]" +
      "{{else}}none{{/each}}";
    expect(render(template, {
      title: "T",
      groups: [
        { name: "a", items: ["x", "y"] },
        { name: "b", items: [] },
      ],
    })).toBe("[0:a/T:0=x;1=y;][1:b/T:empty]");
    expect(render(template, { title: "T", groups: [] })).toBe("none");
  });

  test("if and each blocks can be nested", () => {
    expect(render(
      "{{#each rows}}{{#if active}}{{name}}{{else}}-{{/if}}{{/each}}",
      { rows: [{ name: "A", active: true }, { name: "B", active: false }] },
    )).toBe("A-");
  });

  test("rejects structural mistakes with positions", () => {
    expect(() => render("x\n{{#wat x}}", {})).toThrow("Unknown block 'wat' at line 2, column 1");
    expect(() => render("{{else}}", {})).toThrow("else outside a block at line 1, column 1");
    expect(() => render("{{#if x}}{{else}}{{else}}{{/if}}", {})).toThrow("Duplicate else");
    expect(() => render("{{#if x}}{{/each}}", {})).toThrow("Mismatched closing block");
    expect(() => render("{{#each x}}", {})).toThrow("Unclosed block '#each'");
    expect(() => render("{{/nope}}", {})).toThrow("without an open block");
    expect(() => render("hello {{name", {})).toThrow("Unclosed tag");
  });

  test("rejects non-scalar interpolation", () => {
    expect(() => render("value={{value}}", { value: { nested: true } })).toThrow(
      "Value 'value' is not renderable as scalar text",
    );
    expect(() => render("{{value}}", { value: [1, 2] })).toThrow("not renderable");
  });
});
# Mini Template

A small, dependency-free TypeScript template renderer for Bun.

```ts
import { render } from "./src/engine";

render("Hello, {{user.name}}!", { user: { name: "Ada & Co" } });
// Hello, Ada &amp; Co!
```

Run it from the command line with a UTF-8 template and JSON data file:

```sh
bun run src/cli.ts template.txt data.json
```

The language supports escaped `{{path}}` and raw `{{{path}}}` interpolation,
comments (`{{! ... }}`), nested `if`/`else` blocks, and nested `each`/`else`
blocks. Within `each`, use `{{this}}`, `{{this.field}}`, and `{{@index}}`;
ordinary paths first inspect the current item and then fall back to root data.
Missing values produce no text. Interpolating an object, array, function, or
symbol is an error.

Run the self-tests with:

```sh
bun test
```
